// Channel badges — small colored circle with brand initial
const ChannelBadge = ({ name, size=16 }) => {
  const map = {
    zalo:     { bg: '#0068FF', label: 'Z' },
    facebook: { bg: '#1877F2', label: 'f' },
    messenger:{ bg: '#0084FF', label: 'M' },
    whatsapp: { bg: '#25D366', label: 'W' },
    instagram:{ bg: '#E1306C', label: 'Ig' },
    web:      { bg: '#2B9EF3', label: '⌘' },
    sms:      { bg: '#6B7280', label: '✉' },
    email:    { bg: '#EA4335', label: '@' },
    zns:      { bg: '#0068FF', label: 'Z' },
    viber:    { bg: '#7360F2', label: 'V' },
    telegram: { bg: '#229ED9', label: 'T' },
    line:     { bg: '#06C755', label: 'L' },
    gmail:    { bg: '#EA4335', label: 'G' },
  };
  const c = map[name] || { bg: '#9CA3AF', label: '?' };
  return (
    <span style={{
      width: size, height: size, borderRadius: size,
      background: c.bg, color: 'white',
      fontSize: Math.round(size*0.62), fontWeight: 800,
      display: 'inline-grid', placeItems: 'center', lineHeight: 1,
      fontFamily: 'Plus Jakarta Sans, sans-serif',
      flexShrink: 0,
    }}>{c.label}</span>
  );
};

