try { Object.assign(window, { WIDGET_CATALOG: typeof WIDGET_CATALOG !== 'undefined' ? WIDGET_CATALOG : undefined, DEFAULT_LAYOUT: typeof DEFAULT_LAYOUT !== 'undefined' ? DEFAULT_LAYOUT : undefined, SAVED_VIEWS: typeof SAVED_VIEWS !== 'undefined' ? SAVED_VIEWS : undefined, DB_TEAM: typeof DB_TEAM !== 'undefined' ? DB_TEAM : undefined, DashboardBuilder: typeof DashboardBuilder !== 'undefined' ? DashboardBuilder : undefined, CanvasTab: typeof CanvasTab !== 'undefined' ? CanvasTab : undefined, CanvasGrid: typeof CanvasGrid !== 'undefined' ? CanvasGrid : undefined, TilePreview: typeof TilePreview !== 'undefined' ? TilePreview : undefined, TileInspector: typeof TileInspector !== 'undefined' ? TileInspector : undefined, InsField: typeof InsField !== 'undefined' ? InsField : undefined, ViewsTab: typeof ViewsTab !== 'undefined' ? ViewsTab : undefined, ShareTab: typeof ShareTab !== 'undefined' ? ShareTab : undefined, TemplatesTab: typeof TemplatesTab !== 'undefined' ? TemplatesTab : undefined, ShareModal: typeof ShareModal !== 'undefined' ? ShareModal : undefined, dbStyle: typeof dbStyle !== 'undefined' ? dbStyle : undefined }); } catch(e){ console.error('export dashboard-builder.jsx', e); }

