// Field widget — chip multi-select / date range / slider / select dropdown
function StageField({ field }) {
  const [open, setOpen] = React.useState(false);
  const [picked, setPicked] = React.useState(new Set());
  const [range, setRange] = React.useState(field.value || [field.min, field.max]);
  const [dates, setDates] = React.useState(field.value || ['','']);
  const [sel, setSel] = React.useState('');

  const count = field.t==='chip' ? picked.size
              : field.t==='slider' ? (range[0]!==field.min||range[1]!==field.max ? 1 : 0)
              : field.t==='date' ? (dates[0]||dates[1] ? 1 : 0)
              : field.t==='select' && sel ? 1 : 0;

  const togglePick = (o) => {
    const n = new Set(picked);
    n.has(o) ? n.delete(o) : n.add(o);
    setPicked(n);
  };

  return (
    <div style={{padding:'6px 0', borderBottom:'1px dashed var(--fill-04)'}}>
      <button onClick={()=>setOpen(!open)} style={{
        width:'100%', display:'flex', alignItems:'center', gap:6, padding:'4px 2px',
        background:'transparent', border:'none', cursor:'pointer', textAlign:'left',
        fontSize:12, fontWeight: count>0?700:500,
        color: count>0?'var(--label-01)':'var(--label-02)',
      }}>
        <Icon.ChevronRight style={{width:11, height:11, transform: open?'rotate(90deg)':'none', transition:'transform .15s', color:'var(--label-03)'}}/>
        <span style={{flex:1}}>{field.l}</span>
        {count>0 && <span style={{fontSize:10, fontWeight:700, padding:'1px 6px', borderRadius:8, background:'var(--bg-green)', color:'var(--pr-dark-2)'}}>{count}</span>}
      </button>

      {open && (
        <div style={{padding:'8px 4px 4px 18px'}}>
          {field.t==='chip' && (
            <div style={{display:'flex', flexWrap:'wrap', gap:4}}>
              {field.options.map(o=>{
                const on = picked.has(o);
                return (
                  <button key={o} onClick={()=>togglePick(o)} style={{
                    padding:'3px 9px', borderRadius:12,
                    border:'1px solid '+(on?'var(--primary)':'var(--fill-04)'),
                    background: on?'var(--bg-green)':'white',
                    color: on?'var(--pr-dark-2)':'var(--label-02)',
                    fontSize:11, fontWeight:on?600:500, cursor:'pointer',
                    display:'inline-flex', alignItems:'center', gap:4,
                  }}>
                    {on && <Icon.Check style={{width:9, height:9}}/>} {o}
                  </button>
                );
              })}
            </div>
          )}

          {field.t==='select' && (
            <select value={sel} onChange={e=>setSel(e.target.value)} style={{
              width:'100%', padding:'5px 8px', fontSize:12, borderRadius:6,
              border:'1px solid var(--fill-04)', background:'white', cursor:'pointer'
            }}>
              <option value="">— Chọn —</option>
              {field.options.map(o => <option key={o} value={o}>{o}</option>)}
            </select>
          )}

          {field.t==='date' && (
            <div style={{display:'flex', gap:4, alignItems:'center'}}>
              <input type="date" value={dates[0]} onChange={e=>setDates([e.target.value, dates[1]])} style={{flex:1, padding:'3px 6px', fontSize:11, borderRadius:5, border:'1px solid var(--fill-04)'}}/>
              <span style={{fontSize:10, color:'var(--label-03)'}}>→</span>
              <input type="date" value={dates[1]} onChange={e=>setDates([dates[0], e.target.value])} style={{flex:1, padding:'3px 6px', fontSize:11, borderRadius:5, border:'1px solid var(--fill-04)'}}/>
            </div>
          )}

          {field.t==='slider' && (
            <div>
              <div style={{display:'flex', justifyContent:'space-between', fontSize:10.5, color:'var(--label-02)', marginBottom:4, fontWeight:600}}>
                <span>{range[0]}</span>
                <span style={{color:'var(--label-03)'}}>{field.min} - {field.max}</span>
                <span>{range[1]}</span>
              </div>
              <div style={{position:'relative', height:18}}>
                <div style={{position:'absolute', top:8, left:0, right:0, height:3, background:'var(--fill-03)', borderRadius:2}}/>
                <div style={{
                  position:'absolute', top:8, height:3, borderRadius:2,
                  background:'var(--primary)',
                  left: ((range[0]-field.min)/(field.max-field.min)*100)+'%',
                  width: ((range[1]-range[0])/(field.max-field.min)*100)+'%'
                }}/>
                <input type="range" min={field.min} max={field.max} value={range[0]}
                  onChange={e=>setRange([Math.min(+e.target.value, range[1]), range[1]])}
                  style={{position:'absolute', top:0, left:0, right:0, width:'100%', background:'transparent', appearance:'none', height:18, pointerEvents:'auto'}}
                />
                <input type="range" min={field.min} max={field.max} value={range[1]}
                  onChange={e=>setRange([range[0], Math.max(+e.target.value, range[0])])}
                  style={{position:'absolute', top:0, left:0, right:0, width:'100%', background:'transparent', appearance:'none', height:18}}
                />
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function ContactsModule() {
  const { CONTACTS } = window.AppData;
  const [view, setView]   = useCs('all');
  const [layout, setLayout] = useCs('list'); // list | kanban | chart
  const [stage, setStage] = useCs('all'); // all | lead | potential | consulting | quote | won
  const [selected, setSelected] = useCs([]);
  const [open, setOpen]   = useCs(null);
  const [q, setQ]         = useCs('');
  const [tool, setTool]   = useCs(null); // 'dedupe'|'import'|'export'|'fields'|'zns'|'email'|'meet'|'ticket'|'quote'|'contract'|'order'
  const [more, setMore]   = useCs(false);
  const [bulkToast, setBulkToast] = useCs('');
  const [bulkSub, setBulkSub] = useCs(null);
  React.useEffect(()=>{ if(bulkToast){ const x=setTimeout(()=>setBulkToast(''),1900); return ()=>clearTimeout(x); } }, [bulkToast]);
  const [filterOpen, setFilterOpen] = useCs(false);
  const [mode, setMode]   = useCs('contacts'); // 'contacts' | 'contracts'

  React.useEffect(()=>{
    const apply=()=>{ if(window.__acCusStage){ setStage(window.__acCusStage); window.__acCusStage=null; } };
    apply();
    window.addEventListener('ac-cus-stage', apply);
    return ()=>window.removeEventListener('ac-cus-stage', apply);
  }, []);

  const filtered = CONTACTS.filter(c => {
    if (view==='mine') return c.owner==='Trâm';
    if (view==='unassigned') return c.owner==='Claude Cowork';
    if (view==='vip') return c.tags.includes('VIP');
    if (view==='hot') return c.tags.includes('Lead nóng');
    if (view==='intl') return c.tags.includes('Quốc tế');
    return true;
  }).filter(c => !q || (c.first+' '+c.last+' '+c.email+' '+c.company).toLowerCase().includes(q.toLowerCase()));

  const toggle = (id) => setSelected(s => s.includes(id)?s.filter(x=>x!==id):[...s,id]);

  return (
    <div style={{display:'flex', flexDirection:'column', height:'100%'}}>
      <div className="topbar">
        <h1>Khách hàng</h1>
        <span className="crumb">{stage==='contract'?'Hợp đồng · Ký kết · Gia hạn':'Liên hệ · Khách hàng · Lead'}</span>
        <span className="spacer"/>
        {stage==='contract' ? <>
          <button className="btn btn-ghost btn-sm"><Icon.Filter style={{width:13,height:13}}/> Filter</button>
          <button className="btn btn-ghost btn-sm"><Icon.Download style={{width:13,height:13,transform:'rotate(180deg)'}}/> Xuất Excel</button>
          <button className="btn btn-ghost btn-sm"><Icon.Sparkles/> AI rà soát</button>
          <button className="btn btn-primary"><Icon.Plus/> Hợp đồng mới</button>
        </> : <>
          <button className="btn btn-ghost btn-sm" onClick={()=>setTool('dedupe')}><Icon.Filter style={{width:13,height:13}}/> Check trùng <span className="chip" style={{height:16,padding:'0 6px',fontSize:10,background:'#FEF2F2',color:'#C8263A'}}>12</span></button>
          <button className="btn btn-ghost btn-sm" onClick={()=>setTool('fields')}><Icon.Set style={{width:13,height:13}}/> Trường mở rộng</button>
          <button className="btn btn-ghost btn-sm" onClick={()=>setTool('import')}><Icon.Download style={{width:13,height:13}}/> Nhập</button>
          <button className="btn btn-ghost btn-sm" onClick={()=>setTool('export')}><Icon.Download style={{width:13,height:13,transform:'rotate(180deg)'}}/> Xuất Excel</button>
          <button className="btn btn-primary"><Icon.Plus/> Tạo liên hệ</button>
          {window.AIAssistBtn && <window.AIAssistBtn label="Trợ lý AI" ctx="Liên hệ" cls="btn btn-primary"/>}
        </>}
      </div>

      {/* Pipeline stages: Lead mới → Tiềm năng → Đang tư vấn → Báo giá → Hợp đồng → Đã mua */}
      <div style={{display:'flex', alignItems:'center', gap:6, padding:'8px 20px', background:'white', borderBottom:'1px solid var(--fill-04)', height:46}}>
        {[
          {k:'all',         l:'Tất cả',      c:'var(--label-02)', n:CONTACTS.length},
          {k:'lead',        l:'Lead mới',    c:'#2B9EF3',          n:74},
          {k:'potential',   l:'Tiềm năng',   c:'#F59E0B',          n:52},
          {k:'consulting',  l:'Đang tư vấn', c:'#7C3AED',          n:38},
          {k:'quote',       l:'Báo giá',     c:'#EC4899',          n:21},
          {k:'contract',    l:'Hợp đồng',    c:'#0F6E50',          n:8},
          {k:'won',         l:'Đã mua',      c:'#22C55E',          n:48},
        ].map((s,i,arr)=>{
          const active = stage===s.k;
          return (
            <React.Fragment key={s.k}>
              <button onClick={()=>setStage(s.k)} style={{
                display:'inline-flex', alignItems:'center', gap:7,
                padding:'5px 12px', height:30, borderRadius:16,
                border:'1px solid '+(active?s.c:'var(--fill-04)'),
                background: active?s.c+'14':'white',
                color: active?s.c:'var(--label-01)',
                fontWeight: active?700:600, fontSize:12, cursor:'pointer',
                transition:'all .15s'
              }}>
                <span style={{width:7,height:7,borderRadius:4,background:s.c}}/>
                {s.l}
                <span style={{
                  fontSize:10.5, fontWeight:700, padding:'1px 6px', borderRadius:8,
                  background: active?s.c+'22':'var(--fill-03)',
                  color: active?s.c:'var(--label-02)'
                }}>{s.n}</span>
              </button>
              {i<arr.length-1 && i>0 && <Icon.ArrowRight style={{width:11,height:11,color:'var(--label-04)',opacity:.5}}/>}
            </React.Fragment>
          );
        })}
        <span style={{flex:1}}/>
        <div style={{display:'flex', padding:3, background:'var(--fill-03)', borderRadius:7, gap:2}}>
          {[{k:'list',i:<Icon.List/>,l:'Danh sách'},{k:'kanban',i:<Icon.Grid/>,l:'Kanban'}].map(v=>(
            <button key={v.k} onClick={()=>setLayout(v.k)} style={{
              padding:'4px 9px', border:'none', borderRadius:5, cursor:'pointer',
              background: layout===v.k?'white':'transparent',
              color: layout===v.k?'var(--label-01)':'var(--label-02)',
              boxShadow: layout===v.k?'var(--shadow-sm)':'none', display:'inline-flex', gap:5, alignItems:'center', fontSize:11.5, fontWeight:600
            }}>
              {React.cloneElement(v.i,{style:{width:12,height:12}})}{v.l}
            </button>
          ))}
        </div>
      </div>

      <div style={{flex:1, display:'flex', minHeight:0, background:'var(--fill-02)'}}>
        {stage==='contract' ? <ContractsView/> : <>
        {/* Left rail */}
        <div style={{display:'none', width:240, background:'white', borderRight:'1px solid var(--fill-04)', padding:'14px 0', overflowY:'auto'}}>
          <div style={{padding:'0 14px 6px', display:'flex', alignItems:'center'}}>
            <span style={{fontSize:11, fontWeight:700, letterSpacing:'.05em', color:'var(--label-03)'}}>BỘ LỌC</span>
            <span style={{flex:1}}/>
            <button className="btn-icon" style={{width:20, height:20}}><Icon.Plus style={{width:12,height:12}}/></button>
          </div>
          {(STAGE_FILTERS[stage]||STAGE_FILTERS.all).views.map(v=>{
            const active = view===v.k;
            return (
              <button key={v.k} onClick={()=>setView(v.k)} style={{
                width:'100%', padding:'8px 14px', display:'flex', alignItems:'center', gap:8,
                border:'none', background: active?'var(--bg-green)':'transparent',
                borderLeft:'3px solid '+(active?'var(--primary)':'transparent'),
                cursor:'pointer', textAlign:'left', fontSize:12.5,
                fontWeight: active?600:500, color: active?'var(--pr-dark-2)':'var(--label-01)'
              }}>
                {v.color && <span style={{width:6, height:6, borderRadius:3, background:v.color}}/>}
                <span style={{flex:1}}>{v.l}</span>
              </button>
            );
          })}
          <div style={{margin:'18px 14px 8px', paddingTop:12, borderTop:'1px solid var(--fill-04)'}}>
            <div style={{display:'flex', alignItems:'center', marginBottom:6}}>
              <span style={{fontSize:11, fontWeight:700, color:'var(--label-03)', letterSpacing:'.05em', flex:1}}>LỌC THEO TRƯỜNG</span>
              <button style={{background:'transparent', border:'none', cursor:'pointer', fontSize:10.5, color:'var(--primary)', fontWeight:700}}>Xoá bộ lọc</button>
            </div>
            {((STAGE_FILTERS[stage]||STAGE_FILTERS.all).fields).map(f=>(
              <StageField key={f.l} field={f}/>
            ))}
            <button style={{
              marginTop:10, width:'100%', padding:'6px 8px', fontSize:11, fontWeight:700,
              border:'1px dashed var(--fill-04)', borderRadius:6, background:'white',
              color:'var(--label-02)', cursor:'pointer'
            }}>+ Thêm trường lọc</button>
          </div>
        </div>

        {/* Main */}
        <div style={{flex:1, display:'flex', flexDirection:'column', minWidth:0}}>
          <div style={{padding:'10px 16px', background:'white', borderBottom:'1px solid var(--fill-04)', display:'flex', alignItems:'center', gap:10}}>
            <label style={{display:'inline-flex', alignItems:'center', gap:6, fontSize:12, fontWeight:600}}>
              <input type="checkbox" style={{accentColor:'var(--primary)'}}/>
              <span>{selected.length>0? selected.length+' selected' : 'Select all'}</span>
            </label>
            {true && <>
              <span style={{width:1,height:18,background:'var(--fill-04)'}}/>
              {(()=>{ const STAFF=['Trâm','Minh','Hương','Khoa','Lan Anh']; const TAGS=(window.AppTags?window.AppTags.list().map(t=>t.n):['VIP','Hot lead','Đã chăm sóc','Tiềm năng','Cần gọi lại']); const CAMP=['Flash Sale ZNS','Nhắc tái khám','Win-back 60 ngày','Newsletter Hè'];
                const act=(t)=>{ setBulkToast(t); setBulkSub(null); };
                const BA=[
                  {k:'quote',  l:'Tạo báo giá', i:Icon.Files, run:()=>{ setTool('quote'); }},
                  {k:'contract', l:'Tạo hợp đồng', i:Icon.Note, run:()=>{ setTool('contract'); }},
                  {k:'order',  l:'Tạo đơn hàng', i:Icon.Package, run:()=>{ setTool('order'); }},
                ];
                return BA.map(b=>(
                  b.sep ? <span key={b.k} style={{width:1,height:18,background:'var(--fill-04)',margin:'0 2px'}}/> :
                  <div key={b.k} style={{position:'relative'}}>
                    <button className="btn btn-ghost btn-sm" style={b.danger?{color:'var(--risk)'}:null} onMouseEnter={()=>b.sub&&setBulkSub(b.k)} onClick={()=>{ if(b.sub){ setBulkSub(s=>s===b.k?null:b.k); } else { b.run(); } }}>
                      <b.i style={{width:12,height:12}}/> {b.l}{b.sub && <Icon.ChevronDown style={{width:11,height:11}}/>}
                    </button>
                    {b.sub && bulkSub===b.k && (
                      <div onMouseLeave={()=>setBulkSub(null)} style={{position:'absolute',top:30,left:0,background:'white',border:'1px solid var(--fill-04)',borderRadius:9,boxShadow:'var(--shadow-lg)',padding:5,minWidth:170,zIndex:30}}>
                        {b.sub.map((s,i)=>(<button key={i} onClick={s.run} style={{display:'flex',alignItems:'center',gap:8,width:'100%',padding:'7px 10px',border:'none',background:'transparent',borderRadius:7,cursor:'pointer',textAlign:'left',fontFamily:'inherit',fontSize:12.5,fontWeight:500}} onMouseEnter={e=>e.currentTarget.style.background='var(--fill-02)'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>{s.l}</button>))}
                      </div>
                    )}
                  </div>
                ));
              })()}
            </>}
            <span style={{flex:1}}/>
            <div style={{position:'relative'}}>
              <Icon.Search style={{position:'absolute', left:8, top:7, width:13, height:13, color:'var(--label-03)'}}/>
              <input placeholder="Tìm tên, email, công ty…" value={q} onChange={e=>setQ(e.target.value)} style={{height:28, width:200, paddingLeft:28, border:'1px solid var(--fill-04)', borderRadius:6, fontSize:12, outline:'none'}}/>
            </div>
            {(()=>{ const sst={height:28, border:'1px solid var(--fill-04)', borderRadius:6, fontSize:12, fontFamily:'inherit', background:'white', color:'var(--label-01)', padding:'0 8px', cursor:'pointer'}; return (<>
              <select value={view} onChange={e=>setView(e.target.value)} style={{...sst, fontWeight:600}}>
                {(STAGE_FILTERS[stage]||STAGE_FILTERS.all).views.map(v=><option key={v.k} value={v.k}>{v.l}</option>)}
              </select>
              <select defaultValue="" style={sst}><option value="">Trạng thái</option><option>Đang hoạt động</option><option>Tiềm năng</option><option>Ngủ đông</option></select>
              <select defaultValue="" style={sst}><option value="">Phụ trách</option><option>Trâm</option><option>Minh</option><option>Hương</option><option>Khoa</option></select>
            </>); })()}
            <div style={{position:'relative'}}>
              <button className="btn btn-ghost btn-sm" onClick={()=>setFilterOpen(o=>!o)} style={{borderColor: filterOpen?'var(--primary)':undefined, color: filterOpen?'var(--pr-dark-2)':undefined}}><Icon.Filter/> Lọc</button>
              {filterOpen && <>
                <div onClick={()=>setFilterOpen(false)} style={{position:'fixed', inset:0, zIndex:40}}/>
                <div style={{position:'absolute', right:0, top:'calc(100% + 6px)', zIndex:41, width:260, background:'white', border:'1px solid var(--fill-04)', borderRadius:11, boxShadow:'0 16px 40px rgba(17,24,39,.2)', padding:14}}>
                  <div style={{fontSize:12.5, fontWeight:800, marginBottom:10}}>Lọc nâng cao</div>
                  {[
                    {l:'Nhóm khách hàng', o:['Tất cả nhóm','VIP','Thân thiết','Mới','Doanh nghiệp']},
                    {l:'Nguồn', o:['Tất cả nguồn','Zalo OA','Facebook','Website','Instagram','Giới thiệu']},
                    {l:'Tags', o:['Tất cả tags','#VIP','#Hot lead','#Đơn hàng','#Chăm sóc']},
                    {l:'Pipeline', o:['Tất cả giai đoạn','Lead','Qualified','Proposal','Won','Lost']},
                  ].map(f=>(
                    <div key={f.l} style={{marginBottom:10}}>
                      <div style={{fontSize:11, fontWeight:700, color:'var(--label-02)', marginBottom:4}}>{f.l}</div>
                      <select defaultValue="" style={{width:'100%', height:32, border:'1px solid var(--fill-04)', borderRadius:7, fontSize:12.5, fontFamily:'inherit', background:'white', padding:'0 9px', cursor:'pointer'}}>
                        {f.o.map((x,i)=><option key={i} value={i===0?'':x}>{x}</option>)}
                      </select>
                    </div>
                  ))}
                  <div style={{display:'flex', gap:8, marginTop:12}}>
                    <button onClick={()=>setFilterOpen(false)} className="btn btn-ghost btn-sm" style={{flex:1, justifyContent:'center'}}>Xoá lọc</button>
                    <button onClick={()=>setFilterOpen(false)} className="btn btn-primary btn-sm" style={{flex:1, justifyContent:'center'}}>Áp dụng</button>
                  </div>
                </div>
              </>}
            </div>
            <button className="btn btn-ghost btn-sm"><Icon.Sort/> Sắp xếp</button>
            <button className="btn btn-ghost btn-sm"><Icon.Columns/></button>
          </div>

          <div className="scroll" style={{flex:1, overflow:'auto'}}>
            {layout==='list'   && <ContactList items={filtered} selected={selected} toggle={toggle} open={open} setOpen={setOpen}/>}
            {layout==='kanban' && <ContactKanban items={filtered}/>}
            {layout==='chart'  && <ContactChart items={filtered} stage={stage}/>}
          </div>
        </div>

        {tool && <ContactToolModal kind={tool} count={selected.length} onClose={()=>setTool(null)}/>}
        {bulkToast && <div style={{position:'fixed',bottom:24,left:'50%',transform:'translateX(-50%)',background:'var(--label-01)',color:'white',padding:'10px 18px',borderRadius:10,fontSize:13,fontWeight:600,zIndex:1400,display:'flex',alignItems:'center',gap:8,boxShadow:'0 8px 24px rgba(0,0,0,.2)'}}><Icon.Check style={{width:16,height:16,color:'#4ADE80'}}/>{bulkToast}</div>}

        {open && (
          <>
            <div onClick={()=>setOpen(null)} style={{position:'fixed', inset:0, background:'rgba(15,20,28,.32)', zIndex:60, animation:'c360fade .18s ease'}}/>
            <div style={{position:'fixed', top:0, right:0, bottom:0, width:'min(440px, 94vw)', background:'var(--fill-02)', zIndex:61, display:'flex', flexDirection:'column', boxShadow:'-12px 0 40px rgba(15,20,28,.18)', animation:'c360slide .26s cubic-bezier(.22,.8,.32,1)'}}>
              <div style={{display:'flex', alignItems:'center', gap:10, padding:'12px 16px', background:'white', borderBottom:'1px solid var(--fill-04)', flexShrink:0}}>
                <span style={{width:34, height:34, borderRadius:'50%', background:'var(--primary)', color:'white', display:'grid', placeItems:'center', fontSize:14, fontWeight:800, flexShrink:0}}>{(open.first||'?')[0]}</span>
                <div style={{flex:1, minWidth:0}}>
                  <div style={{fontSize:14, fontWeight:800, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis'}}>{open.last} {open.first}</div>
                  <div style={{fontSize:11, color:'var(--label-03)'}}>Hồ sơ 360° AI · {open.company||'Khách hàng'}</div>
                </div>
                <button className="btn-icon" onClick={()=>setOpen(null)} title="Đóng"><Icon.Close style={{width:16, height:16}}/></button>
              </div>
              <div style={{flex:1, overflow:'hidden', display:'flex'}}>
                {window.Customer360Panel ? <Customer360Panel/> : (window.Customer360Module ? <Customer360Module/> : <ContactDetail c={open} onClose={()=>setOpen(null)}/>)}
              </div>
            </div>
            <style>{`@keyframes c360slide{from{transform:translateX(40px);opacity:0}to{transform:translateX(0);opacity:1}}@keyframes c360fade{from{opacity:0}to{opacity:1}}`}</style>
          </>
        )}
        </>}
      </div>
    </div>
  );
}

function ContractsView(){
  const CONTRACTS = [
    {id:'HD-2026-0421-001', name:'Hợp đồng phân phối độc quyền Q2',     party:'Gia Dụng Sài Gòn',    value:'1.2 tỷ ₫',  start:'01/04/2026', end:'30/06/2026', status:'active',  signed:true,  daysLeft:71},
    {id:'HD-2026-0418-014', name:'Hợp đồng mua bán hàng B2C',           party:'Shop Bé Na',         value:'285 M ₫',   start:'18/04/2026', end:'18/04/2027', status:'active',  signed:true,  daysLeft:362},
    {id:'HD-2026-0415-008', name:'Hợp đồng dịch vụ Claude Cowork',      party:'MomBaby Vietnam',    value:'120 M ₫',   start:'15/04/2026', end:'15/04/2027', status:'active',  signed:true,  daysLeft:359},
    {id:'HD-2026-0410-022', name:'Hợp đồng cung cấp catalogue 2026',    party:'Nhà cung cấp Miền Bắc',  value:'420 M ₫',   start:'10/04/2026', end:'10/10/2026', status:'expiring',signed:true,  daysLeft:25},
    {id:'HD-2026-0408-005', name:'Hợp đồng affiliate KOL',              party:'Chị Lan · Beauty',   value:'45 M ₫',    start:'08/04/2026', end:'08/07/2026', status:'pending', signed:false, daysLeft:null},
    {id:'HD-2026-0405-011', name:'Hợp đồng dịch vụ ship miền Nam',      party:'GHN Express',        value:'180 M ₫',   start:'05/04/2026', end:'05/04/2027', status:'active',  signed:true,  daysLeft:349},
    {id:'HD-2025-1220-098', name:'Hợp đồng mua sỉ Q4 2025',              party:'Gia Dụng Sài Gòn',    value:'890 M ₫',   start:'20/12/2025', end:'20/03/2026', status:'expired', signed:true,  daysLeft:-30},
    {id:'HD-2026-0403-002', name:'NDA bảo mật dữ liệu khách hàng',       party:'Cloud Provider',     value:'—',         start:'03/04/2026', end:'03/04/2028', status:'active',  signed:true,  daysLeft:722},
  ];
  const STATUS = {
    active:   {l:'Đang hiệu lực', c:'#16A34A', bg:'#DCFCE7'},
    expiring: {l:'Sắp hết hạn',    c:'#D97706', bg:'#FEF3C7'},
    pending:  {l:'Chờ ký',          c:'#2563EB', bg:'#DBEAFE'},
    expired:  {l:'Đã hết hạn',     c:'#DC2626', bg:'#FEE2E2'},
  };
  const [status, setStatus] = React.useState('all');
  const [opened, setOpened] = React.useState(null);
  const counts = {
    all: CONTRACTS.length,
    active: CONTRACTS.filter(c=>c.status==='active').length,
    expiring: CONTRACTS.filter(c=>c.status==='expiring').length,
    pending: CONTRACTS.filter(c=>c.status==='pending').length,
    expired: CONTRACTS.filter(c=>c.status==='expired').length,
  };
  const rows = status==='all' ? CONTRACTS : CONTRACTS.filter(c=>c.status===status);
  const KPIS = [
    {l:'Tổng giá trị', v:'3.14 tỷ ₫', s:'+18% YoY', c:'#16A34A', i:Icon.Dollar},
    {l:'Đang hiệu lực', v:counts.active, s:'5 khách hàng', c:'#2563EB', i:Icon.Check},
    {l:'Sắp hết hạn', v:counts.expiring, s:'< 30 ngày', c:'#D97706', i:Icon.Clock},
    {l:'Chờ ký', v:counts.pending, s:'1 cần nhắc', c:'#7C3AED', i:Icon.Edit},
  ];
  return (
    <div style={{flex:1, display:'flex', flexDirection:'column', overflow:'hidden', background:'var(--fill-02)'}}>
      <div style={{display:'flex', gap:12, padding:'14px 20px', background:'white', borderBottom:'1px solid var(--fill-04)'}}>
        {KPIS.map(k=>{const I=k.i; return (
          <div key={k.l} style={{flex:1, padding:'12px 14px', background:'white', border:'1px solid var(--fill-04)', borderRadius:10, display:'flex', alignItems:'center', gap:12}}>
            <div style={{width:36,height:36,borderRadius:9,background:k.c+'15',color:k.c,display:'grid',placeItems:'center'}}><I style={{width:16,height:16}}/></div>
            <div style={{minWidth:0, flex:1}}>
              <div style={{fontSize:11.5,color:'var(--label-03)',marginBottom:2}}>{k.l}</div>
              <div style={{fontSize:18,fontWeight:700,color:'var(--label-01)',lineHeight:1.1}}>{k.v}</div>
              <div style={{fontSize:11,color:k.c,fontWeight:600,marginTop:2}}>{k.s}</div>
            </div>
          </div>
        );})}
      </div>
      <div style={{display:'flex', alignItems:'center', gap:6, padding:'8px 20px', background:'white', borderBottom:'1px solid var(--fill-04)'}}>
        {[{k:'all',l:'Tất cả',c:'var(--label-02)',n:counts.all},{k:'active',l:'Đang hiệu lực',c:'#16A34A',n:counts.active},{k:'expiring',l:'Sắp hết hạn',c:'#D97706',n:counts.expiring},{k:'pending',l:'Chờ ký',c:'#2563EB',n:counts.pending},{k:'expired',l:'Đã hết hạn',c:'#DC2626',n:counts.expired}].map(s=>{
          const a = status===s.k;
          return (
            <button key={s.k} onClick={()=>setStatus(s.k)} style={{
              display:'flex',alignItems:'center',gap:6,padding:'6px 12px',borderRadius:18,
              border:'1px solid '+(a?s.c:'var(--fill-04)'), background:a?s.c+'14':'white',
              color:a?s.c:'var(--label-01)', fontSize:12.5, fontWeight:a?700:500, cursor:'pointer'
            }}>
              <span style={{width:6,height:6,borderRadius:3,background:s.c}}/>
              {s.l}
              <span style={{padding:'1px 7px',borderRadius:10,background:a?s.c+'22':'var(--fill-03)',color:a?s.c:'var(--label-03)',fontSize:11,fontWeight:700}}>{s.n}</span>
            </button>
          );
        })}
      </div>
      <div style={{flex:1, overflow:'auto', padding:'12px 20px'}}>
        <div style={{background:'white', borderRadius:10, border:'1px solid var(--fill-04)', overflow:'hidden'}}>
          <div style={{display:'grid', gridTemplateColumns:'180px 1.4fr 1fr 110px 180px 130px 90px', gap:0, padding:'10px 14px', background:'var(--fill-02)', borderBottom:'1px solid var(--fill-04)', fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:.4, color:'var(--label-03)'}}>
            <div>Số HĐ</div><div>Tên hợp đồng</div><div>Đối tác</div><div>Giá trị</div><div>Thời hạn</div><div>Trạng thái</div><div style={{textAlign:'right'}}>Thao tác</div>
          </div>
          {rows.map(c=>{
            const st = STATUS[c.status];
            return (
              <div key={c.id} onClick={()=>setOpened(c)} style={{display:'grid', gridTemplateColumns:'180px 1.4fr 1fr 110px 180px 130px 90px', gap:0, padding:'12px 14px', borderBottom:'1px solid var(--fill-04)', fontSize:12.5, alignItems:'center', cursor:'pointer', background: opened&&opened.id===c.id?'#F8FAFC':'white'}}
                onMouseEnter={e=>{if(!(opened&&opened.id===c.id)) e.currentTarget.style.background='var(--fill-02)';}}
                onMouseLeave={e=>{if(!(opened&&opened.id===c.id)) e.currentTarget.style.background='white';}}>
                <div style={{fontFamily:'monospace', fontSize:11.5, color:'var(--label-02)', fontWeight:600}}>{c.id}</div>
                <div style={{fontWeight:600, color:'var(--label-01)', display:'flex', alignItems:'center', gap:7}}>
                  {c.signed ? <Icon.Check style={{width:13,height:13,color:'#16A34A'}}/> : <Icon.Clock style={{width:13,height:13,color:'#2563EB'}}/>}
                  {c.name}
                </div>
                <div style={{color:'var(--label-02)'}}>{c.party}</div>
                <div style={{fontWeight:700, color:'var(--label-01)'}}>{c.value}</div>
                <div style={{fontSize:11.5, color:'var(--label-02)'}}>
                  <div>{c.start} → {c.end}</div>
                  {c.daysLeft!==null && <div style={{fontSize:10.5, color:c.daysLeft<0?'#DC2626':(c.daysLeft<30?'#D97706':'var(--label-03)'), fontWeight:600, marginTop:2}}>{c.daysLeft<0?'Quá hạn '+Math.abs(c.daysLeft)+' ngày':'Còn '+c.daysLeft+' ngày'}</div>}
                </div>
                <div><span style={{display:'inline-flex',alignItems:'center',gap:5,padding:'3px 9px',borderRadius:11,background:st.bg,color:st.c,fontSize:11.5,fontWeight:600}}><span style={{width:5,height:5,borderRadius:3,background:st.c}}/>{st.l}</span></div>
                <div style={{display:'flex', gap:4, justifyContent:'flex-end'}} onClick={e=>e.stopPropagation()}>
                  <button title="Xem" onClick={()=>setOpened(c)} style={{width:26,height:26,border:'1px solid var(--fill-04)',borderRadius:6,background:'white',display:'grid',placeItems:'center',cursor:'pointer'}}><Icon.Eye style={{width:12,height:12}}/></button>
                  <button title="Sửa" style={{width:26,height:26,border:'1px solid var(--fill-04)',borderRadius:6,background:'white',display:'grid',placeItems:'center',cursor:'pointer'}}><Icon.Edit style={{width:12,height:12}}/></button>
                  <button title="Thêm" style={{width:26,height:26,border:'1px solid var(--fill-04)',borderRadius:6,background:'white',display:'grid',placeItems:'center',cursor:'pointer'}}><Icon.More style={{width:12,height:12}}/></button>
                </div>
              </div>
            );
          })}
        </div>
      </div>
      {opened && <ContractDrawer contract={opened} status={STATUS[opened.status]} onClose={()=>setOpened(null)}/>}
    </div>
  );
}

function ContractDrawer({ contract, status, onClose }) {
  const [tab, setTab] = React.useState('overview');
  const timeline = [
    {t:'Đã tạo',          d:contract.start, by:'Trâm · Sales',       i:Icon.Edit,   c:'#94A3B8'},
    {t:'Gửi duyệt nội bộ', d:contract.start, by:'CEO Mai Đình Ngọc',   i:Icon.Send,   c:'#2563EB'},
    {t:'Phê duyệt',       d:contract.start, by:'Phòng Pháp chế',     i:Icon.Check,  c:'#16A34A'},
    contract.signed
      ? {t:'Đã ký số',    d:contract.start, by:contract.party+' · FastSign', i:Icon.Check, c:'#16A34A'}
      : {t:'Chờ đối tác ký', d:'Chờ', by:contract.party,            i:Icon.Clock,  c:'#D97706'},
    {t:'Có hiệu lực',     d:contract.start, by:'Tự động',            i:Icon.Star,   c:contract.signed?'#16A34A':'#94A3B8'},
    contract.status==='expiring' || contract.status==='expired'
      ? {t:'Nhắc gia hạn', d:'14 ngày trước HSD', by:'Workflow auto', i:Icon.Bell, c:'#D97706'}
      : null,
  ].filter(Boolean);
  const appendices = [
    {id:'PL-01', name:'Phụ lục 01 — Bảng giá Q2',        date:contract.start, value:'Có hiệu lực', signed:true},
    {id:'PL-02', name:'Phụ lục 02 — Điều khoản giao hàng', date:contract.start, value:'Có hiệu lực', signed:true},
    contract.status==='expiring' ? {id:'PL-03', name:'Phụ lục 03 — Gia hạn hợp đồng', date:'Đang soạn', value:'Bản nháp', signed:false} : null,
  ].filter(Boolean);
  const files = [
    {name:contract.id+'.pdf',           size:'2.4 MB',  type:'PDF',  by:'Trâm',  d:contract.start},
    {name:'Phụ lục 01.pdf',             size:'860 KB', type:'PDF',   by:'Trâm',  d:contract.start},
    {name:'Phụ lục 02.pdf',             size:'1.1 MB', type:'PDF',   by:'Pháp chế', d:contract.start},
    {name:'Bảng giá Q2.xlsx',           size:'420 KB', type:'XLSX',  by:'Sales', d:contract.start},
    {name:'Chữ ký số đối tác.p7s',      size:'12 KB',  type:'P7S',   by:'FastSign', d:contract.start},
  ];
  const TABS = [
    {k:'overview', l:'Tổng quan',    i:Icon.Files},
    {k:'timeline', l:'Timeline ký',  i:Icon.Activity},
    {k:'appendix', l:'Phụ lục',      i:Icon.Note},
    {k:'files',    l:'File đính kèm',i:Icon.Download},
  ];

  return (
    <>
      <div onClick={onClose} style={{position:'fixed', inset:0, background:'rgba(15,20,28,.40)', zIndex:60}}/>
      <div style={{
        position:'fixed', top:0, right:0, bottom:0, width:'min(720px, 92vw)', background:'white',
        zIndex:61, display:'flex', flexDirection:'column', boxShadow:'-12px 0 40px rgba(15,20,28,.20)'
      }}>
        {/* Header */}
        <div style={{padding:'14px 20px', borderBottom:'1px solid var(--fill-04)'}}>
          <div style={{display:'flex', alignItems:'center', gap:10}}>
            <button onClick={onClose} className="btn-icon" title="Đóng" style={{width:30,height:30,borderRadius:7,border:'1px solid var(--fill-04)',background:'white',display:'grid',placeItems:'center',cursor:'pointer'}}>
              <Icon.Close style={{width:14, height:14}}/>
            </button>
            <span style={{fontFamily:'monospace', fontSize:11.5, color:'var(--label-02)', fontWeight:600}}>{contract.id}</span>
            <span style={{display:'inline-flex',alignItems:'center',gap:5,padding:'3px 9px',borderRadius:11,background:status.bg,color:status.c,fontSize:11,fontWeight:700}}>
              <span style={{width:5,height:5,borderRadius:3,background:status.c}}/>{status.l}
            </span>
            <span style={{flex:1}}/>
            <button className="btn btn-ghost btn-sm"><Icon.Download style={{width:13,height:13}}/> Tải PDF</button>
            <button className="btn btn-ghost btn-sm"><Icon.Edit style={{width:13,height:13}}/> Sửa</button>
            <button className="btn btn-primary btn-sm"><Icon.Send style={{width:13,height:13}}/> Gửi đối tác</button>
          </div>
          <div style={{marginTop:12, display:'flex', alignItems:'center', gap:10}}>
            <div style={{width:48,height:48,borderRadius:10,background:'linear-gradient(135deg, #DBEAFE, #BFDBFE)',color:'#1E40AF',display:'grid',placeItems:'center',flexShrink:0}}>
              <Icon.Files style={{width:22,height:22}}/>
            </div>
            <div style={{flex:1, minWidth:0}}>
              <div style={{fontSize:17, fontWeight:700, color:'var(--label-01)', lineHeight:1.25}}>{contract.name}</div>
              <div style={{fontSize:12, color:'var(--label-02)', marginTop:3}}>{contract.party} · {contract.start} → {contract.end} · <b style={{color:'var(--label-01)'}}>{contract.value}</b></div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div style={{display:'flex', gap:0, padding:'0 20px', borderBottom:'1px solid var(--fill-04)', background:'white'}}>
          {TABS.map(t=>{const I=t.i; const a=tab===t.k; return (
            <button key={t.k} onClick={()=>setTab(t.k)} style={{
              padding:'10px 14px', background:'transparent', border:'none',
              borderBottom:'2px solid '+(a?'var(--primary)':'transparent'),
              color: a?'var(--primary)':'var(--label-02)',
              fontSize:12.5, fontWeight: a?700:500, cursor:'pointer',
              display:'inline-flex', alignItems:'center', gap:6, marginBottom:-1
            }}>
              <I style={{width:13,height:13}}/>{t.l}
            </button>
          );})}
        </div>

        {/* Body */}
        <div style={{flex:1, overflow:'auto', padding:'18px 20px', background:'var(--fill-02)'}}>
          {tab==='overview' && (
            <div style={{display:'flex', flexDirection:'column', gap:14}}>
              <div style={{background:'white', border:'1px solid var(--fill-04)', borderRadius:10, padding:14}}>
                <div style={{fontSize:11, fontWeight:700, color:'var(--label-03)', textTransform:'uppercase', letterSpacing:'.05em', marginBottom:10}}>Thông tin hợp đồng</div>
                {[
                  ['Loại HĐ',    contract.name.includes('NDA')?'NDA bảo mật':contract.name.includes('phân phối')?'Phân phối':contract.name.includes('mua sỉ')?'Mua sỉ B2B':'Dịch vụ'],
                  ['Số HĐ',      contract.id],
                  ['Đối tác',    contract.party],
                  ['Giá trị',    contract.value],
                  ['Hiệu lực từ',contract.start],
                  ['Hết hiệu lực', contract.end],
                  ['Phụ trách',  'Trâm · Sales Lead'],
                  ['Người duyệt','Mai Đình Ngọc · CEO'],
                  ['Phương thức ký', contract.signed?'FastSign · Ký số điện tử':'Chờ ký số'],
                ].map(([l,v])=>(
                  <div key={l} style={{display:'grid', gridTemplateColumns:'140px 1fr', gap:10, padding:'7px 0', borderBottom:'1px dashed var(--fill-04)', fontSize:12.5}}>
                    <span style={{color:'var(--label-02)'}}>{l}</span>
                    <span style={{color:'var(--label-01)', fontWeight:500}}>{v}</span>
                  </div>
                ))}
              </div>

              <div style={{background:'white', border:'1px solid var(--fill-04)', borderRadius:10, padding:14}}>
                <div style={{display:'flex', alignItems:'center', marginBottom:10}}>
                  <Icon.Sparkles style={{width:13, height:13, color:'#7C3AED'}}/>
                  <span style={{marginLeft:6, fontSize:11, fontWeight:700, color:'#7C3AED', textTransform:'uppercase', letterSpacing:'.05em'}}>AI rà soát</span>
                  <span style={{flex:1}}/>
                  <span style={{padding:'2px 8px', borderRadius:10, background:'#DCFCE7', color:'#15803D', fontSize:10.5, fontWeight:700}}>An toàn 92/100</span>
                </div>
                <div style={{fontSize:12.5, color:'var(--label-02)', lineHeight:1.6}}>
                  • Điều khoản giá: <b style={{color:'#16A34A'}}>OK</b> · phù hợp khung phân phối Q2.<br/>
                  • Bảo hành 12 tháng: <b style={{color:'#16A34A'}}>Đầy đủ</b>.<br/>
                  • Điều khoản phạt vi phạm: <b style={{color:'#D97706'}}>Đề xuất rõ hơn</b> — hiện chỉ ghi "theo thoả thuận".<br/>
                  • Chữ ký số 2 bên: <b style={{color: contract.signed?'#16A34A':'#DC2626'}}>{contract.signed?'Hoàn tất':'Còn thiếu đối tác'}</b>.
                </div>
              </div>
            </div>
          )}

          {tab==='timeline' && (
            <div style={{background:'white', border:'1px solid var(--fill-04)', borderRadius:10, padding:'16px 18px'}}>
              <div style={{fontSize:11, fontWeight:700, color:'var(--label-03)', textTransform:'uppercase', letterSpacing:'.05em', marginBottom:12}}>Quy trình ký kết</div>
              <div style={{position:'relative', paddingLeft:24}}>
                <div style={{position:'absolute', left:11, top:8, bottom:8, width:2, background:'var(--fill-04)'}}/>
                {timeline.map((e,i)=>{const I=e.i; return (
                  <div key={i} style={{position:'relative', paddingBottom:18, paddingLeft:8}}>
                    <div style={{position:'absolute', left:-19, top:0, width:22,height:22, borderRadius:11, background:e.c+'18', color:e.c, border:'2px solid white', boxShadow:'0 0 0 1px '+e.c, display:'grid', placeItems:'center'}}>
                      <I style={{width:11, height:11}}/>
                    </div>
                    <div style={{fontSize:13, fontWeight:600, color:'var(--label-01)'}}>{e.t}</div>
                    <div style={{fontSize:11.5, color:'var(--label-02)', marginTop:2}}>{e.by} · <b style={{color:e.c}}>{e.d}</b></div>
                  </div>
                );})}
              </div>
            </div>
          )}

          {tab==='appendix' && (
            <div style={{display:'flex', flexDirection:'column', gap:8}}>
              {appendices.map(a=>(
                <div key={a.id} style={{background:'white', border:'1px solid var(--fill-04)', borderRadius:10, padding:'12px 14px', display:'flex', alignItems:'center', gap:12}}>
                  <div style={{width:36,height:36,borderRadius:8,background:a.signed?'#DCFCE7':'#FEF3C7',color:a.signed?'#15803D':'#92400E',display:'grid',placeItems:'center'}}>
                    <Icon.Note style={{width:16,height:16}}/>
                  </div>
                  <div style={{flex:1, minWidth:0}}>
                    <div style={{fontSize:13, fontWeight:600}}>{a.name}</div>
                    <div style={{fontSize:11, color:'var(--label-03)', marginTop:2}}>{a.id} · {a.date} · {a.value}</div>
                  </div>
                  <button className="btn btn-ghost btn-sm" style={{height:26, fontSize:11}}><Icon.Eye style={{width:11,height:11}}/> Xem</button>
                  <button className="btn btn-ghost btn-sm" style={{height:26, fontSize:11}}><Icon.Download style={{width:11,height:11}}/></button>
                </div>
              ))}
              <button style={{marginTop:6, padding:'10px', border:'1px dashed var(--fill-04)', borderRadius:10, background:'white', cursor:'pointer', fontSize:12, fontWeight:600, color:'var(--label-02)', display:'inline-flex', alignItems:'center', justifyContent:'center', gap:6}}>
                <Icon.Plus style={{width:13,height:13}}/> Thêm phụ lục mới
              </button>
            </div>
          )}

          {tab==='files' && (
            <div style={{background:'white', border:'1px solid var(--fill-04)', borderRadius:10, overflow:'hidden'}}>
              <div style={{display:'grid', gridTemplateColumns:'1.8fr 80px 90px 110px 100px', padding:'10px 14px', background:'var(--fill-02)', borderBottom:'1px solid var(--fill-04)', fontSize:11, fontWeight:700, color:'var(--label-03)', textTransform:'uppercase', letterSpacing:'.04em'}}>
                <div>Tên file</div><div>Loại</div><div>Kích thước</div><div>Người tải lên</div><div style={{textAlign:'right'}}>Thao tác</div>
              </div>
              {files.map((f,i)=>(
                <div key={i} style={{display:'grid', gridTemplateColumns:'1.8fr 80px 90px 110px 100px', padding:'12px 14px', alignItems:'center', borderBottom:i<files.length-1?'1px solid var(--fill-04)':'none', fontSize:12.5}}>
                  <div style={{display:'flex',alignItems:'center',gap:8,minWidth:0}}>
                    <div style={{width:30,height:30,borderRadius:7,background:f.type==='PDF'?'#FEE2E2':f.type==='XLSX'?'#DCFCE7':'#E0E7FF',color:f.type==='PDF'?'#991B1B':f.type==='XLSX'?'#15803D':'#3730A3',display:'grid',placeItems:'center',fontSize:9,fontWeight:800,flexShrink:0}}>{f.type}</div>
                    <span style={{fontWeight:500, overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{f.name}</span>
                  </div>
                  <div style={{fontSize:11, color:'var(--label-02)'}}>{f.type}</div>
                  <div style={{fontSize:11, color:'var(--label-02)'}}>{f.size}</div>
                  <div style={{fontSize:11, color:'var(--label-02)'}}>{f.by}</div>
                  <div style={{display:'flex', gap:4, justifyContent:'flex-end'}}>
                    <button style={{width:24,height:24,border:'1px solid var(--fill-04)',borderRadius:5,background:'white',display:'grid',placeItems:'center',cursor:'pointer'}}><Icon.Eye style={{width:11,height:11}}/></button>
                    <button style={{width:24,height:24,border:'1px solid var(--fill-04)',borderRadius:5,background:'white',display:'grid',placeItems:'center',cursor:'pointer'}}><Icon.Download style={{width:11,height:11}}/></button>
                  </div>
                </div>
              ))}
              <div style={{padding:'12px 14px', background:'var(--fill-02)', borderTop:'1px solid var(--fill-04)'}}>
                <button style={{width:'100%', padding:'8px', border:'1px dashed var(--fill-04)', borderRadius:7, background:'white', cursor:'pointer', fontSize:12, fontWeight:600, color:'var(--label-02)', display:'inline-flex', alignItems:'center', justifyContent:'center', gap:6}}>
                  <Icon.Plus style={{width:13,height:13}}/> Đính kèm file mới
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

function LastTouchCell({c}){
  const TYPES = [
    {k:'meeting', l:'Meeting', i:'Calendar',      c:'#7C3AED'},
    {k:'call',    l:'Cuộc gọi', i:'Phone',         c:'#22C55E'},
    {k:'email',   l:'Email',   i:'Mail',          c:'#0EA5E9'},
    {k:'zns',     l:'ZNS',     i:'MessageSquare', c:'#F59E0B'},
  ];
  const hash = (c.id||'').split('').reduce((a,b)=>a+b.charCodeAt(0),0);
  const t = TYPES[hash % TYPES.length];
  const IconC = Icon[t.i] || Icon.Activity;
  const subjects = {
    meeting: 'Demo gói Pro · 30 phút',
    call:    'Tư vấn báo giá Q2',
    email:   'Gửi báo giá Q2-2026',
    zns:     'Nhắc lịch follow-up',
  };
  return (
    <div style={{display:'flex', alignItems:'center', gap:9, minWidth:0}}>
      <div style={{width:30,height:30,borderRadius:8,background:t.c+'15',color:t.c,display:'grid',placeItems:'center',flexShrink:0,border:'1px solid '+t.c+'30'}}>
        <IconC style={{width:13,height:13}}/>
      </div>
      <div style={{minWidth:0,flex:1,lineHeight:1.3}}>
        <div style={{fontSize:12, fontWeight:600, color:'var(--label-01)', overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{subjects[t.k]}</div>
        <div style={{fontSize:10.5,color:'var(--label-03)',marginTop:1,display:'flex',alignItems:'center',gap:5,minWidth:0}}>
          <span style={{color:t.c,fontWeight:600,whiteSpace:'nowrap',flexShrink:0}}>{t.l}</span>
          <span style={{width:2,height:2,borderRadius:1,background:'var(--label-04)',flexShrink:0}}/>
          <span style={{whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{c.lastActivity||'—'}</span>
        </div>
      </div>
    </div>
  );
}

function RowActions({c}){
  const [open, setOpen] = React.useState(false);
  const [sub, setSub] = React.useState(null); // 'assign' | 'forward'
  const STAFF = ['Trâm','Minh','Hương','Khoa'];
  const TEAMS = ['Nhóm Kinh doanh','Nhóm CSKH','Nhóm Kế toán'];
  const items = [
    {l:'Xem chi tiết', i:Icon.Eye || Icon.MessageSquare, c:'#0EA5E9'},
    {l:'Cập nhật thông tin', i:Icon.Plus,          c:'#1B9E5A'},
    {l:'Sửa khách hàng',     i:Icon.Edit,          c:'#2B9EF3'},
    {l:'Gán phụ trách', i:Icon.User || Icon.Users, c:'#7C9CFF', sub:'assign'},
    {l:'Chuyển tiếp',  i:Icon.ArrowRight || Icon.Send, c:'#C9820B', sub:'forward'},
    {l:'Xoá',          i:Icon.Trash,         c:'#DC2626'},
  ];
  return (
    <div style={{position:'relative', justifySelf:'end'}} onClick={e=>e.stopPropagation()}>
      <button title="Thao tác" onClick={()=>setOpen(!open)} style={{
        width:30,height:30,borderRadius:8,border:'1px solid var(--fill-04)',
        background: open?'var(--fill-03)':'white',display:'grid',placeItems:'center',cursor:'pointer'
      }}
      onMouseEnter={e=>{if(!open) e.currentTarget.style.background='var(--fill-02)';}}
      onMouseLeave={e=>{if(!open) e.currentTarget.style.background='white';}}>
        <Icon.More style={{width:14,height:14}}/>
      </button>
      {open && (
        <>
          <div onClick={()=>{setOpen(false);setSub(null);}} style={{position:'fixed',inset:0,zIndex:90}}/>
          <div style={{
            position:'absolute', top:34, right:0, zIndex:91,
            background:'white', border:'1px solid var(--fill-04)', borderRadius:10,
            boxShadow:'0 12px 32px rgba(15,23,42,.14), 0 2px 6px rgba(15,23,42,.06)',
            padding:5, minWidth:180, overflow:'hidden'
          }}>
            {items.map((it,i)=>{
              const IconC = it.i;
              return (
                <button key={it.l} onClick={()=>{ if(it.sub){ setSub(it.sub); } else { setOpen(false); } }} style={{
                  width:'100%', display:'flex', alignItems:'center', gap:9,
                  padding:'8px 10px', border:'none', borderRadius:6,
                  background:'transparent', cursor:'pointer', textAlign:'left',
                  fontSize:12.5, fontWeight:500, color:it.l==='Xoá'?'#DC2626':'var(--label-01)'
                }}
                onMouseEnter={e=>{e.currentTarget.style.background=it.c+'12';}}
                onMouseLeave={e=>{e.currentTarget.style.background='transparent';}}>
                  <IconC style={{width:13,height:13,color:it.c}}/> <span style={{flex:1}}>{it.l}</span>
                  {it.sub && <span style={{color:'var(--label-04)'}}>›</span>}
                </button>
              );
            })}
            {sub && (
              <div style={{borderTop:'1px solid var(--fill-03)', marginTop:4, paddingTop:4}}>
                <div style={{fontSize:9.5, fontWeight:800, letterSpacing:'.05em', textTransform:'uppercase', color:'var(--label-03)', padding:'4px 10px 5px'}}>{sub==='assign'?'Gán cho cá nhân':'Chuyển tiếp tới'}</div>
                {(sub==='forward' ? [...STAFF, ...TEAMS] : STAFF).map(n=>(
                  <button key={n} onClick={()=>{ setOpen(false); setSub(null); }} style={{width:'100%', display:'flex', alignItems:'center', gap:8, padding:'7px 10px', border:'none', borderRadius:6, background:'transparent', cursor:'pointer', textAlign:'left', fontSize:12, fontWeight:500, color:'var(--label-01)', fontFamily:'inherit'}}
                    onMouseEnter={e=>e.currentTarget.style.background='var(--fill-02)'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                    {(TEAMS.includes(n)? (Icon.Users && <Icon.Users style={{width:13,height:13,color:'var(--label-03)'}}/>) : <span style={{width:18,height:18,borderRadius:'50%',background:'#7C9CFF',color:'white',display:'grid',placeItems:'center',fontSize:9,fontWeight:800,flexShrink:0}}>{n[0]}</span>)}
                    <span style={{flex:1}}>{n}</span>
                  </button>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

function ContactList({items, selected, toggle, open, setOpen}) {
  const lcMap = {
    'Khách hàng':  {bg:'rgba(45,197,106,.15)', c:'#0F5E33'},
    'Lead':      {bg:'#DBEAFE', c:'#1E40AF'},
    'Khách tiềm năng':  {bg:'#FEF3C7', c:'#92400E'},
    'Cơ hội':{bg:'#F3E8FF', c:'#6B21A8'},
    'Đối tác':   {bg:'#FCE7F3', c:'#9F1239'},
  };
  const lcDefault = {bg:'#F1F5F9', c:'#475569'};
  const lc = new Proxy(lcMap, { get: (t,k) => t[k] || lcDefault });
  return (
    <div style={{background:'white'}}>
      <div style={{display:'grid', gridTemplateColumns:'30px minmax(150px,1.25fr) 96px 88px minmax(140px,1fr) 120px 106px 90px 64px 80px 80px',
        gap:10, padding:'12px 16px', fontSize:11, color:'var(--label-02)', fontWeight:700, textTransform:'uppercase',
        letterSpacing:.4, borderBottom:'1px solid var(--fill-04)', background:'var(--fill-02)', position:'sticky', top:0, zIndex:1}}>
        <span/><span>Tên khách hàng</span><span>Ngày đăng ký</span><span>Kênh</span><span>Email</span><span>SĐT</span><span>Zalo</span><span>Khu vực</span><span>Quận</span><span>Phụ trách</span><span style={{justifySelf:'end'}}>Thao tác</span>
      </div>
      {items.map(c => {
        const active = open && open.id===c.id;
        return (
          <div key={c.id} onClick={()=>setOpen(c)} style={{
            display:'grid', gridTemplateColumns:'30px minmax(150px,1.25fr) 96px 88px minmax(140px,1fr) 120px 106px 90px 64px 80px 80px',
            gap:10, padding:'14px 16px', fontSize:13, alignItems:'center',
            borderBottom:'1px solid var(--fill-04)', cursor:'pointer',
            background: active?'var(--bg-green)':'white'
          }} onMouseEnter={e=>{if(!active) e.currentTarget.style.background='var(--fill-02)'}} onMouseLeave={e=>{if(!active) e.currentTarget.style.background='white'}}>
            <div onClick={e=>{e.stopPropagation(); toggle(c.id);}}>
              <input type="checkbox" checked={selected.includes(c.id)} onChange={()=>{}} style={{accentColor:'var(--primary)'}}/>
            </div>
            <div style={{display:'flex', gap:9, alignItems:'center', minWidth:0}}>
              <div className="avatar sm" style={{background:'hsl('+((c.first+c.last).length*28)%360+' 55% 48%)', width:30, height:30, fontSize:11, flexShrink:0}}>{c.first[0]}{c.last[0]}</div>
              <div style={{minWidth:0}}>
                <div style={{fontWeight:600, color:'var(--primary)', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}>{c.last} {c.first}</div>
                <div style={{fontSize:10.5, color:'var(--label-03)', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}>{c.title}</div>
              </div>
            </div>
            {(()=>{ const D=['08/06/2026','09/06/2026','10/06/2026','11/06/2026','12/06/2026','13/06/2026']; const H=['09:12','10:40','11:25','14:08','15:33','16:50']; const i=(c.id+c.first).length; const CH=[['Zalo OA','#0068FF'],['Facebook','#1877F2'],['Website','#0E9B94'],['TikTok','#111'],['Giới thiệu','#C9820B']]; const ch=CH[(c.first+c.last+c.id).length%CH.length]; const CITY=[['TP.HCM','Q.1'],['TP.HCM','Q.7'],['Hà Nội','Cầu Giấy'],['Đà Nẵng','Hải Châu'],['TP.HCM','Thủ Đức'],['Hà Nội','Đống Đa']]; const cw=CITY[i%CITY.length]; const zalo='0'+(900000000+ (i*37%99999999)); return (<>
              <div style={{fontSize:11.5, whiteSpace:'nowrap'}}><div style={{fontWeight:600}}>{D[i%6]}</div><div style={{fontSize:10, color:'var(--label-03)'}}>{H[i%6]}</div></div>
              <span style={{display:'inline-flex', alignItems:'center', gap:5, fontSize:11.5, fontWeight:600, justifySelf:'start'}}><span style={{width:7,height:7,borderRadius:4,background:ch[1]}}/>{ch[0]}</span>
              <div style={{fontSize:11.5, color:'var(--info)', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}>{c.email}</div>
              <div style={{fontSize:11.5, fontFamily:'monospace'}}>{c.phone}</div>
              <div style={{fontSize:11.5, fontFamily:'monospace', color:'#0068FF'}}>{zalo}</div>
              <div style={{fontSize:11.5, fontWeight:600, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis'}}>{cw[0]}</div>
              <div style={{fontSize:11.5, color:'var(--label-02)', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis'}}>{cw[1]}</div>
            </>); })()}
            <div style={{fontSize:11.5, display:'flex', alignItems:'center', gap:5, minWidth:0}}>
              <div className="avatar sm" style={{background: c.owner==='Claude Cowork'?'var(--grad-signature)':'hsl('+((c.owner||'').length*34)%360+' 50% 48%)', width:20, height:20, fontSize:9.5, flexShrink:0}}>{c.owner==='Claude Cowork'?'✦':c.owner[0]}</div>
              <span style={{whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis'}}>{c.owner}</span>
            </div>
            <RowActions c={c}/>
          </div>
        );
      })}
      {items.length===0 && <div style={{padding:60, textAlign:'center', color:'var(--label-03)'}}>Không có contact nào khớp.</div>}
    </div>
  );
}

function ContactKanban({items}) {
  const stages = ['Lead','Khách tiềm năng','Cơ hội','Khách hàng','Đối tác'];
  const colors = {'Lead':'#2B9EF3', 'Khách tiềm năng':'#F59E0B', 'Cơ hội':'#7C3AED', 'Khách hàng':'#22C55E', 'Đối tác':'#EC4899'};
  return (
    <div style={{padding:16, display:'grid', gridTemplateColumns:`repeat(${stages.length}, minmax(230px, 1fr))`, gap:12, minHeight:'100%'}}>
      {stages.map(s=>(
        <div key={s} style={{background:'var(--fill-02)', borderRadius:10, padding:10}}>
          <div style={{display:'flex', alignItems:'center', gap:6, padding:'2px 4px 10px'}}>
            <span style={{width:8, height:8, borderRadius:4, background:colors[s]}}/>
            <span style={{fontSize:12, fontWeight:700, textTransform:'uppercase', letterSpacing:.4}}>{s}</span>
            <span style={{fontSize:11, color:'var(--label-03)'}}>{items.filter(c=>c.lifecycle===s).length}</span>
          </div>
          {items.filter(c=>c.lifecycle===s).map(c=>(
            <div key={c.id} className="card" style={{padding:10, marginBottom:8}}>
              <div style={{display:'flex', gap:8, alignItems:'center', marginBottom:6}}>
                <div className="avatar sm" style={{background:'hsl('+((c.first+c.last).length*28)%360+' 55% 48%)', width:26, height:26, fontSize:10}}>{c.first[0]}{c.last[0]}</div>
                <div style={{minWidth:0, flex:1}}>
                  <div style={{fontWeight:600, fontSize:12.5, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}>{c.last} {c.first}</div>
                  <div style={{fontSize:10, color:'var(--label-03)'}}>{c.company || c.account}</div>
                </div>
              </div>
              <div style={{fontSize:10.5, color:'var(--label-02)'}}>📧 {c.email}</div>
              <div style={{fontSize:10.5, color:'var(--label-02)', marginTop:2}}>💰 {c.totalValue}</div>
              <div style={{display:'flex', gap:4, marginTop:6}}>
                {c.tags.slice(0,2).map(t=>(<span key={t} className="chip outline" style={{height:16, fontSize:9.5, padding:'0 5px'}}>{t}</span>))}
              </div>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

