const INTEG_CATS = ['Tất cả','CRM','TMĐT','Thanh toán','Năng suất','ERP & Vận hành'];
function IntegLogo({ n, c, size=40 }){
  return <span style={{width:size, height:size, borderRadius:11, background:c, color:'white', display:'grid', placeItems:'center', flexShrink:0, fontWeight:800, fontSize:size*0.42, boxShadow:'0 2px 6px '+c+'55'}}>{n[0]}</span>;
}
function PageIntegrations() {
  const [cat, setCat] = useSet('Tất cả');
  const [q, setQ] = useSet('');
  const list = INTEG_APPS.filter(a => (cat==='Tất cả'||a.cat===cat) && (!q.trim() || a.n.toLowerCase().includes(q.toLowerCase())));
  const connected = INTEG_APPS.filter(a=>a.on).length;
  return (
    <div>
      {/* Hero */}
      <div className="card" style={{padding:'22px 24px', marginBottom:18, background:'linear-gradient(135deg, var(--bg-green), rgba(255,255,255,0))', border:'1px solid var(--pr-light-2)'}}>
        <div style={{display:'flex', alignItems:'center', gap:18, flexWrap:'wrap'}}>
          <div style={{flex:1, minWidth:240}}>
            <div style={{fontSize:20, fontWeight:800, marginBottom:4}}>Tích hợp ứng dụng</div>
            <div style={{fontSize:13, color:'var(--label-02)', lineHeight:1.5}}>Kết nối AppChat với CRM, TMĐT, thanh toán, ERP và công cụ năng suất — tự động hoá toàn bộ luồng dữ liệu.</div>
          </div>
          <div style={{display:'flex', gap:26}}>
            <div><div style={{fontSize:24, fontWeight:800, color:'var(--pr-dark-2)'}}>{INTEG_APPS.length}</div><div style={{fontSize:11, color:'var(--label-03)'}}>ứng dụng</div></div>
            <div><div style={{fontSize:24, fontWeight:800, color:'#16A34A'}}>{connected}</div><div style={{fontSize:11, color:'var(--label-03)'}}>đã kết nối</div></div>
            <div><div style={{fontSize:24, fontWeight:800, color:'var(--label-01)'}}>6</div><div style={{fontSize:11, color:'var(--label-03)'}}>nhóm</div></div>
          </div>
        </div>
      </div>
      {/* Toolbar */}
      <div style={{display:'flex', alignItems:'center', gap:10, marginBottom:16, flexWrap:'wrap'}}>
        <div style={{position:'relative', flex:'1 1 240px', maxWidth:320}}>
          <Icon.Search style={{position:'absolute', left:11, top:9, width:14, height:14, color:'var(--label-03)'}}/>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Tìm ứng dụng tích hợp…" style={{height:36, width:'100%', paddingLeft:34, border:'1px solid var(--fill-04)', borderRadius:9, fontSize:13, outline:'none', fontFamily:'inherit', boxSizing:'border-box'}}/>
        </div>
        <div style={{display:'flex', gap:6, flexWrap:'wrap'}}>
          {INTEG_CATS.map(ca=>{ const on=cat===ca; return (
            <button key={ca} onClick={()=>setCat(ca)} style={{padding:'7px 14px', borderRadius:20, fontSize:12.5, fontWeight:700, cursor:'pointer', fontFamily:'inherit', border:'1px solid '+(on?'var(--primary)':'var(--fill-04)'), background:on?'var(--bg-green)':'white', color:on?'var(--pr-dark-2)':'var(--label-02)'}}>{ca}</button>
          );})}
        </div>
      </div>
      {/* Grid */}
      <div style={{display:'grid', gridTemplateColumns:'repeat(3, 1fr)', gap:14}}>
        {list.map(a=>(
          <div key={a.n} className="card" style={{padding:0, overflow:'hidden', display:'flex', flexDirection:'column'}}>
            <div style={{padding:16, flex:1}}>
              <div style={{display:'flex', alignItems:'flex-start', gap:12, marginBottom:10}}>
                <IntegLogo n={a.n} c={a.c}/>
                <div style={{flex:1, minWidth:0}}>
                  <div style={{fontSize:14, fontWeight:800}}>{a.n}</div>
                  <div style={{fontSize:10.5, fontWeight:700, color:'var(--label-03)', textTransform:'uppercase', letterSpacing:'.04em', marginTop:2}}>{a.cat}</div>
                </div>
                {a.on && <span style={{fontSize:9.5, fontWeight:800, padding:'3px 9px', borderRadius:10, background:'#DCFCE7', color:'#15803D', flexShrink:0}}>● Đã kết nối</span>}
              </div>
              <div style={{fontSize:12, color:'var(--label-02)', lineHeight:1.55}}>{a.d}</div>
            </div>
            <div style={{display:'flex', alignItems:'center', padding:'11px 16px', borderTop:'1px solid var(--fill-03)'}}>
              <span style={{flex:1}}/>
              {a.on
                ? <button className="btn btn-ghost btn-sm" style={{borderColor:'var(--fill-04)'}}>Quản lý</button>
                : <button className="btn btn-primary btn-sm" style={{fontWeight:700}}>Kết nối</button>}
            </div>
          </div>
        ))}
        {list.length===0 && <div style={{gridColumn:'1/-1', padding:48, textAlign:'center', color:'var(--label-03)', fontSize:13}}>Không tìm thấy ứng dụng phù hợp.</div>}
      </div>
    </div>
  );
}

